+// ErrBuildLockExists reports that strict acquisition found an occupied Build lock path.
+var ErrBuildLockExists = errors.New("Build lock path already exists")
+
+// AcquireBuildStrict takes a Build lock only after exclusive creation.
+func AcquireBuildStrict(root string) (*Lock, error) {
+	l := NewLock(BuildLockPath(root))
+	if err := os.MkdirAll(filepath.Dir(l.Path), 0o755); err != nil {
+		return nil, err
+	}
+	f, err := os.OpenFile(l.Path, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o644)
+	if errors.Is(err, os.ErrExist) {
+		return nil, fmt.Errorf("lock %s: %w", l.Path, ErrBuildLockExists)
+	}
+	if err != nil {
+		return nil, err
+	}
+	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
+		f.Close()
+		return nil, fmt.Errorf("lock %s: %w", l.Path, err)
+	}
+	if !sameEntry(f, l.Path) {
+		f.Close()
+		return nil, fmt.Errorf("lock %s changed during acquisition", l.Path)
+	}
+	token := newToken()
+	body := fmt.Sprintf("%s\npid %d\ntoken %s\n", lockHeader, os.Getpid(), token)
+	if _, err := f.WriteAt([]byte(body), 0); err != nil {
+		f.Close()
+		return nil, err
+	}
+	l.f, l.token, l.strictPath = f, token, true
+	return l, nil
+}
+
+func sameEntry(f *os.File, path string) bool {
+	a, err1 := f.Stat()
+	b, err2 := os.Lstat(path)
+	return err1 == nil && err2 == nil && os.SameFile(a, b)
+}

